document.addEventListener('click',event=>{const target=event.target.closest('[data-action]');if(!target)return;const {action,id}=target.dataset;
 if(action==='person'){showPerson(id);}else if(action==='detailBack'){backDetail();}else if(action==='searchHit'){openSearchResult(id);}else if(action==='moreSearch'){appState.search.searchLimit+=12;renderSearchResults();}else if(action==='pin'){togglePin(id);}else if(action==='clearEvent'){appState.session.activeEventId=null;render();}else if(action==='relatedOnly'){appState.conditions.selected=new Set(activeEvent()?.states||[]);for(const state of appState.layout.pinned)appState.conditions.selected.add(state);render();}else if(action==='eventChart'){if(id!==appState.session.activeEventId)focusEvent(id);closeDetail(false);setCursor(activeEvent().year,true);}else if(action==='participant'){const [eid,index]=id.split(':');const e=D.events.find(e=>e.id===eid),p=e?.participants[Number(index)];if(p)showPerson(p.id);}else if(action==='comboApply'){applyCombo(id);$('#combinations').close();}else if(action==='comboDelete'){appState.session.savedCombos=appState.session.savedCombos.filter(c=>c.id!==id);saveCombos();renderCombos();}else if(action==='state')showState(id);else if(action==='ruler')showRuler(id);else if(action==='event')showEvent(id);else if(action==='cluster'){const es=id.split(',').map(id=>D.events.find(e=>e.id===id));show('密集事件 · 按年代展开','<h3 class="detailTitle">'+es.length+'条事件</h3>'+eventList(es),'cluster:'+id);}else if(action==='locate'){if(Number(id)<appState.conditions.end){$('#extend').checked=true;setExtension(true);}if(!appState.conditions.selected.size)appState.conditions.selected=new Set(D.states.map(s=>s.id));setCursor(Number(id),true);closeDetail(false);}
});
